// Modern approach: Custom hook (preferred for most cases)
function useMousePosition(): MousePosition {
  const [position, setPosition] = useState<MousePosition>({ x: 0, y: 0 });
  useEffect(() => {
    const handler = (e: MouseEvent) => setPosition({ x: e.clientX, y: e.clientY });
    window.addEventListener('mousemove', handler);
    return () => window.removeEventListener('mousemove', handler);
  }, []);
  return position;
}

// Usage with hook is cleaner
function Cursor(): JSX.Element {
  const { x, y } = useMousePosition();
  return <div style={{ left: x, top: y }} className="cursor" />;
}

// HOC for auth protection (still useful)
function withAuth<T extends object>(
  Component: ComponentType<T>
): ComponentType<T> {
  return function AuthGuard(props: T): JSX.Element {
    const { user } = useAuth();
    if (!user) return <Navigate to="/login" />;
    return <Component {...props} />;
  };
}

